"""English pluralization library with ordered rules, irregulars, and invariants."""

IRREGULARS = {
    "child": "children",
    "mouse": "mice",
    "goose": "geese",
    "foot": "feet",
    "tooth": "teeth",
    "person": "people",
    "criterion": "criteria",
    "phenomenon": "phenomena",
    "cactus": "cacti",
    "analysis": "analyses",
    "basis": "bases",
    "datum": "data",
}

INVARIANTS = {
    "sheep", "deer", "fish", "species", "series", "aircraft",
}

F_TO_VES = {"leaf", "wolf", "knife", "life", "half", "shelf", "loaf", "thief"}

O_ES = {"hero", "potato", "tomato", "echo", "veto"}

VOWELS = set("aeiou")

# Reverse maps for singularize()
SINGULAR_IRREGULARS = {p: s for s, p in IRREGULARS.items()}


def _ends_consonant_y(word: str) -> bool:
    return len(word) >= 2 and word.endswith("y") and word[-2] not in VOWELS


def pluralize(noun: str) -> str:
    """Pluralize a noun using irregulars -> invariants -> ordered suffix rules."""
    if noun in IRREGULARS:
        return IRREGULARS[noun]
    if noun in INVARIANTS:
        return noun
    if noun in F_TO_VES:
        stem = noun[:-2] if noun.endswith("fe") else noun[:-1]
        return stem + "ves"
    if noun.endswith(("s", "x", "z", "ch", "sh")):
        return noun + "es"
    if _ends_consonant_y(word=noun):
        return noun[:-1] + "ies"
    if noun in O_ES:
        return noun + "es"
    return noun + "s"


def _try_strip_suffix(word: str, suffix: str, replacement: str):
    if word.endswith(suffix) and len(word) > len(suffix):
        return replacement + word[: -len(suffix)]
    return None


def singularize(noun: str) -> str:
    """Singularize a noun by inverting irregulars, invariants, and unambiguous rules."""
    if noun in SINGULAR_IRREGULARS:
        return SINGULAR_IRREGULARS[noun]
    if noun in INVARIANTS:
        return noun
    # -ves -> f/fe (only for the known f/fe set; ambiguous otherwise)
    candidate = _try_strip_suffix(noun, "ves", "")
    if candidate is not None:
        if candidate + "f" in F_TO_VES:
            return candidate + "f"
        if candidate + "fe" in F_TO_VES:
            return candidate + "fe"
    # -ies -> consonant+y
    candidate = _try_strip_suffix(noun, "ies", "")
    if candidate is not None and _ends_consonant_y(word=candidate + "y"):
        return candidate + "y"
    # -(e)s from s/x/z/ch/sh rule
    for suffix in ("ches", "shes", "ses", "xes", "zes"):
        candidate = _try_strip_suffix(noun, suffix, "")
        if candidate is not None:
            base = candidate
            if suffix == "ses":
                # could be +es after s/z or plain +s; prefer restoring via rules
                if base.endswith(("s", "z")):
                    return base
            elif suffix in ("ches", "shes"):
                if base.endswith(("ch", "sh")):
                    return base
            else:
                return base
    # -oes / -es for the o-es set
    candidate = _try_strip_suffix(noun, "oes", "")
    if candidate is not None and candidate in O_ES:
        return candidate
    # default: strip final s
    candidate = _try_strip_suffix(noun, "s", "")
    if candidate is not None:
        return candidate
    raise ValueError(f"cannot singularize: {noun!r}")

