def singularize(noun: str) -> str:
    """Singularize a noun by inverting irregulars, invariants, and unambiguous rules.

    Candidate stems are generated in rule priority order; the first stem whose
    pluralize() reproduces the input wins, guaranteeing round-trips.
    """
    if noun in SINGULAR_IRREGULARS:
        return SINGULAR_IRREGULARS[noun]
    if noun in INVARIANTS:
        return noun

    candidates = []
    if noun.endswith("ves") and len(noun) > 3:
        stem = noun[:-3]
        candidates += [stem + "f", stem + "fe"]
    if noun.endswith("ies") and len(noun) > 3:
        candidates.append(noun[:-3] + "y")
    if noun.endswith("oes") and len(noun) > 3:
        candidates.append(noun[:-3] + "o")
    if noun.endswith("es") and len(noun) > 2:
        # undoes the s/x/z/ch/sh rule
        candidates.append(noun[:-2])
    if noun.endswith("s") and len(noun) > 1:
        # default +s rule
        candidates.append(noun[:-1])

    for candidate in candidates:
        if pluralize(candidate) == noun:
            return candidate
    raise ValueError(f"cannot singularize: {noun!r}")

